  text-transform: uppercase; margin-bottom: clamp(36px, 6vh, 70px);
}
.start-brand .mark, .brand .mark { width: 26px; height: 26px; border: 1px solid var(--line-strong); border-radius: 50%; display: grid; place-items: center; position: relative; }
.start-brand .mark::before, .brand .mark::before { content: ""; width: 13px; height: 1px; background: var(--mint); transform: rotate(-45deg); box-shadow: 0 0 8px var(--mint); }
.start-brand .mark::after, .brand .mark::after { content: ""; position: absolute; width: 5px; height: 5px; border: 1px solid var(--mint); border-radius: 50%; right: 4px; top: 6px; }
.start-brand .mark i, .brand .mark i { position: absolute; inset: -4px; border: 1px dashed rgba(116,240,200,.22); border-radius: 50%; animation: spin 18s linear infinite; }
@keyframes spin { to { transform: rotate(360deg) } }
.start-brand .dot { width: 3px; height: 3px; border-radius: 50%; background: var(--mint); }
.kicker, .eyebrow {
  font-family: var(--mono); font-size: 10px; letter-spacing: .26em; text-transform: uppercase; color: var(--mint);
}
.start-copy .kicker { margin-bottom: 14px; display: flex; align-items: center; gap: 10px; }
.start-copy .kicker::before { content: ""; width: 34px; height: 1px; background: var(--mint); }
h1 {
  font-size: clamp(72px, 11vw, 158px);
  line-height: .78; letter-spacing: -.055em; font-weight: 900;
  text-transform: uppercase; margin-bottom: 28px;
  text-shadow: 0 0 50px rgba(20, 120, 100, .18);
}
h1 span {
  color: transparent;
  -webkit-text-stroke: 2px var(--mint);
  text-shadow: 0 0 34px rgba(116, 240, 200, .28);
}
.lede {
  max-width: 520px; font-size: clamp(14px, 1.4vw, 17px); line-height: 1.65;
  color: #b9cdc7; margin-bottom: 32px;
}
.lede strong { color: var(--text); font-weight: 600; }
.start-facts {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 0;
  border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);
  margin: 0 0 34px; max-width: 600px;
}
.start-facts > div { padding: 16px 18px 16px 0; display: grid; gap: 3px; }
.start-facts > div + div { border-left: 1px solid var(--line); padding-left: 18px; }
.start-facts span { font-family: var(--mono); font-size: 9px; color: var(--mint); letter-spacing: .16em; }
.start-facts b { font-size: 13px; letter-spacing: .12em; text-transform: uppercase; }
.start-facts em { font-style: normal; font-size: 11px; color: var(--muted); line-height: 1.4; }

.start-actions { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.primary-btn {
  position: relative; display: inline-flex; align-items: center; gap: 18px;
  min-height: 58px; padding: 0 28px;
  background: var(--mint); color: #032019;
  font-size: 12px; font-weight: 800; letter-spacing: .16em; text-transform: uppercase;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
  box-shadow: 0 0 40px rgba(116, 240, 200, .22);
  transition: transform .18s, box-shadow .18s, background .18s;
}
.primary-btn i { width: 20px; height: 20px; transition: transform .2s; }
.primary-btn:hover { transform: translateY(-2px); background: var(--mint-bright); box-shadow: 0 0 60px rgba(116, 240, 200, .36); }
.primary-btn:hover i { transform: translateX(4px); }
.primary-btn:active { transform: translateY(0) scale(.99); }
.primary-btn.compact { min-height: 48px; width: 100%; justify-content: space-between; margin-top: 18px; }
.ghost-btn {
  min-height: 52px; padding: 0 20px; display: inline-flex; flex-direction: column; align-items: flex-start; justify-content: center; gap: 2px;
  border: 1px solid var(--line-strong); background: rgba(8, 20, 20, .5);
  font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
  transition: background .2s, border-color .2s;
}
.ghost-btn small { font-family: var(--mono); font-size: 9px; color: var(--mint); letter-spacing: .1em; }
.ghost-btn:hover { background: rgba(116, 240, 200, .1); border-color: var(--mint); }
.start-controls { display: flex; flex-wrap: wrap; gap: 8px 18px; margin-top: 26px; font-size: 10px; color: var(--muted); }
.start-controls span { display: inline-flex; align-items: center; gap: 7px; }
.start-note { margin-top: 20px; font-size: 10px; color: var(--dim); letter-spacing: .02em; }

.start-aside { align-self: center; justify-self: end; display: grid; gap: 22px; width: min(310px, 100%); }
.sim-card {
  background: rgba(4, 12, 14, .58); border: 1px solid var(--line);
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  padding: 18px 20px 16px; box-shadow: var(--shadow);
  clip-path: polygon(0 0, calc(100% - 20px) 0, 100% 20px, 100% 100%, 0 100%);
}
.sim-head { display: flex; align-items: center; gap: 9px; font-family: var(--mono); font-size: 9px; letter-spacing: .18em; color: var(--mint); padding-bottom: 14px; border-bottom: 1px solid var(--line); }
.pulse { width: 6px; height: 6px; border-radius: 50%; background: var(--mint); box-shadow: 0 0 0 0 rgba(116,240,200,.6); animation: pulse 2s infinite; }
@keyframes pulse { 0% { box-shadow: 0 0 0 0 rgba(116,240,200,.6) } 70% { box-shadow: 0 0 0 8px rgba(116,240,200,0) } 100% { box-shadow: 0 0 0 0 rgba(116,240,200,0) } }
.sim-row { display: flex; justify-content: space-between; align-items: baseline; padding: 12px 0; border-bottom: 1px solid rgba(116,240,200,.07); font-family: var(--mono); font-size: 9px; letter-spacing: .14em; color: var(--muted); }
.sim-row b { font-family: var(--sans); font-size: 12px; letter-spacing: .1em; color: var(--text); text-transform: uppercase; }
.sim-footer { display: flex; align-items: center; gap: 8px; padding-top: 14px; font-family: var(--mono); font-size: 8px; letter-spacing: .18em; color: var(--dim); }
.sim-footer .bar { width: 26px; height: 2px; background: var(--mint); box-shadow: 0 0 8px var(--mint); }
.aside-quote { font-size: 15px; line-height: 1.55; color: var(--muted); padding-left: 18px; border-left: 1px solid var(--line); font-style: italic; }
.aside-quote em { color: var(--mint); font-style: normal; }
.start-foot {
  position: relative; z-index: 2; display: flex; justify-content: space-between;
  padding: 14px clamp(26px, 6vw, 100px) calc(18px + var(--safe-b));
  font-family: var(--mono); font-size: 8px; letter-spacing: .18em; color: var(--dim); text-transform: uppercase;
}

/* ==========================================================================
   HUD GENERAL
   ========================================================================== */
#hud { position: fixed; inset: 0; z-index: 10; pointer-events: none; }
#hud > * { pointer-events: none; }
#hud button, #hud .hotbar, #hud .panel { pointer-events: auto; }
#topbar {
  position: absolute; top: 0; left: 0; right: 0;
  display: flex; align-items: flex-start; justify-content: space-between;
  padding: calc(16px + var(--safe-t)) calc(20px + var(--safe-r)) 0 calc(20px + var(--safe-l));
  gap: 16px;
}
.brand { display: flex; align-items: center; gap: 12px; min-height: 46px; }
.brand .mark { width: 38px; height: 38px; background: rgba(5,13,14,.65); backdrop-filter: blur(8px); }
.brand-name { display: flex; flex-direction: column; font-size: 14px; font-weight: 900; letter-spacing: .16em; line-height: 1; }
.brand-name small { font-family: var(--mono); font-size: 8px; color: var(--mint); letter-spacing: .2em; margin-top: 5px; font-weight: 400; }

.trial-pill {
  position: absolute; left: 50%; top: calc(16px + var(--safe-t)); transform: translateX(-50%);
  width: min(250px, 36vw); padding: 10px 14px 11px;
  background: rgba(5,13,15,.72); border: 1px solid var(--line);
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
}
.trial-top { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--mono); font-size: 8px; letter-spacing: .18em; color: var(--muted); }
.trial-top b { font-size: 10px; color: var(--mint); letter-spacing: .12em; }
.trial-pill.trial-active { border-color: rgba(255,107,125,.45); animation: trialDanger 2.4s ease-in-out infinite; }
.trial-pill.trial-active .trial-top b { color: var(--red); }
@keyframes trialDanger { 0%,100% { box-shadow: 0 0 0 rgba(255,107,125,0) } 50% { box-shadow: 0 0 26px rgba(255,107,125,.28) } }
.trial-track { height: 3px; background: rgba(255,255,255,.1); margin-top: 7px; overflow: hidden; }
.trial-track i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, var(--mint-dim), var(--mint)); box-shadow: 0 0 8px var(--mint); transition: width .6s; }
.trial-pill.trial-active .trial-track i { background: var(--red); box-shadow: 0 0 10px var(--red); }

.top-right { display: flex; align-items: center; gap: 8px; }
.clock-card { text-align: right; padding: 6px 12px 6px 0; border-right: 1px solid var(--line); margin-right: 4px; }
.clock-card span { display: block; font-family: var(--mono); font-size: 15px; letter-spacing: .06em; }
.clock-card small { display: block; font-family: var(--mono); font-size: 8px; color: var(--muted); letter-spacing: .14em; margin-top: 2px; }
.icon-btn {
  width: 40px; height: 40px; padding: 10px; display: grid; place-items: center;
  color: var(--muted); background: rgba(5,13,15,.62); border: 1px solid var(--line);
  backdrop-filter: blur(8px); transition: color .2s, border-color .2s, background .2s;
}
.icon-btn:hover { color: var(--mint); border-color: var(--line-strong); background: rgba(116,240,200,.08); }
.icon-btn.close { width: 34px; height: 34px; padding: 8px; }
.icon-btn.muted { color: var(--red); }

/* objective */
.objective-panel {
  position: absolute; left: calc(20px + var(--safe-l)); top: calc(92px + var(--safe-t));
  width: 264px; padding: 14px 16px 13px;
  background: linear-gradient(135deg, rgba(5,14,16,.82), rgba(5,14,16,.52));
  border: 1px solid var(--line); border-left: 2px solid var(--mint);
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  transition: opacity .3s, transform .3s;
}
.obj-head { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 8px; letter-spacing: .2em; color: var(--mint); margin-bottom: 9px; }
.obj-head b { color: var(--muted); font-weight: 400; }
.obj-title { font-size: 13px; font-weight: 700; letter-spacing: .04em; margin-bottom: 3px; }
.obj-sub { font-size: 10px; line-height: 1.45; color: var(--muted); }
.obj-sub kbd { height: 17px; min-width: 17px; font-size: 8px; vertical-align: middle; }
.obj-list { margin-top: 10px; display: grid; gap: 4px; }
.obj-row { display: flex; align-items: center; gap: 8px; font-size: 9px; color: var(--dim); letter-spacing: .04em; }
.obj-row i { width: 12px; height: 12px; border: 1px solid rgba(255,255,255,.14); display: grid; place-items: center; flex: 0 0 auto; }
.obj-row i svg { width: 8px; height: 8px; opacity: 0; }
.obj-row.done { color: var(--muted); text-decoration: line-through; text-decoration-color: rgba(116,240,200,.4); }
.obj-row.done i { border-color: var(--mint); background: rgba(116,240,200,.16); }
.obj-row.done i svg { opacity: 1; color: var(--mint); }

/* reticle */
#reticle { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); display: grid; place-items: center; }
.ret-dot { width: 5px; height: 5px; border-radius: 50%; background: rgba(231,245,239,.8); box-shadow: 0 0 0 4px rgba(255,255,255,.04), 0 0 10px rgba(116,240,200,.4); transition: all .2s; }
#reticle.valid .ret-dot { width: 10px; height: 10px; background: var(--mint); box-shadow: 0 0 0 5px rgba(116,240,200,.13), 0 0 18px var(--mint); }
#reticle.invalid .ret-dot { background: var(--red); box-shadow: 0 0 0 5px rgba(255,107,125,.12), 0 0 14px var(--red); }
#reticle.hot .ret-dot { width: 13px; height: 13px; background: transparent; border: 1px solid var(--amber); box-shadow: 0 0 14px rgba(255,200,107,.4); }
.ret-label {
  position: absolute; top: 20px; white-space: nowrap; font-family: var(--mono); font-size: 9px;
  letter-spacing: .14em; color: var(--mint); text-transform: uppercase;
  text-shadow: 0 2px 8px #000; opacity: 0; transition: opacity .2s;
}
#reticle.show-label .ret-label { opacity: 1; }
#reticle.invalid .ret-label { color: var(--red); }
#reticle.hot .ret-label { color: var(--amber); }

/* hint strip + interact */
.hint-strip {
  position: absolute; left: 50%; bottom: calc(101px + var(--safe-b)); transform: translateX(-50%);
  padding: 7px 14px; font-family: var(--mono); font-size: 8px; letter-spacing: .14em; color: var(--muted);
  background: rgba(5,13,15,.55); border: 1px solid rgba(116,240,200,.09); white-space: nowrap;
  transition: opacity .4s;
}
.interact-prompt {
  position: absolute; left: 50%; bottom: calc(150px + var(--safe-b)); transform: translateX(-50%);
  display: flex; align-items: center; gap: 8px; padding: 7px 12px;
  background: rgba(5,13,15,.78); border: 1px solid var(--line-strong);
  font-family: var(--mono); font-size: 9px; letter-spacing: .14em; color: var(--text); text-transform: uppercase;
}

/* vitals */
.vitals {
  position: absolute; left: calc(20px + var(--safe-l)); bottom: calc(22px + var(--safe-b));
  width: 236px; display: grid; gap: 6px;
  padding: 11px 12px; background: rgba(5,13,15,.55); border: 1px solid var(--line);
  backdrop-filter: blur(8px);
}
.vital { display: grid; grid-template-columns: 26px 1fr 28px; align-items: center; gap: 7px; }
.v-icon { font-family: var(--mono); font-size: 8px; color: var(--muted); letter-spacing: .04em; }
.v-track { height: 5px; background: rgba(255,255,255,.1); overflow: hidden; position: relative; }
.v-track i { display: block; height: 100%; width: 100%; transition: width .3s; }
.vital b { font-family: var(--mono); font-size: 9px; font-weight: 400; color: var(--muted); text-align: right; }
.vital[data-vital="health"] .v-track i { background: linear-gradient(90deg, #b33d4c, var(--red)); }
.vital[data-vital="hunger"] .v-track i { background: linear-gradient(90deg, #ad772b, var(--amber)); }
.vital[data-vital="thirst"] .v-track i { background: linear-gradient(90deg, #2a718e, #65d5ff); }
.vital[data-vital="energy"] .v-track i { background: linear-gradient(90deg, #6c56bd, var(--violet)); }
.vital.energy { opacity: .8; }
.vital.low .v-track i { animation: barFlare .9s ease-in-out infinite; }
@keyframes barFlare { 50% { opacity: .45 } }

/* hotbar */
.hotbar {
  position: absolute; left: 50%; bottom: calc(24px + var(--safe-b)); transform: translateX(-50%);
  display: flex; gap: 6px; padding: 6px; background: rgba(4,11,13,.6);
  border: 1px solid var(--line); backdrop-filter: blur(10px);
}
.slot {
  position: relative; width: 57px; height: 57px; display: grid; place-items: center;
  background: rgba(255,255,255,.035); border: 1px solid rgba(255,255,255,.07);
  color: var(--muted); transition: background .15s, border-color .15s, transform .15s;
}
.slot:hover { background: rgba(116,240,200,.08); }
.slot.active { border-color: var(--mint); background: rgba(116,240,200,.12); color: var(--mint); box-shadow: inset 0 0 20px rgba(116,240,200,.09); }
.slot.empty { opacity: .35; }
.slot .slot-icon { width: 25px; height: 25px; }
.slot .slot-key { position: absolute; left: 4px; top: 3px; font-family: var(--mono); font-size: 7px; color: var(--dim); }
.slot .slot-count { position: absolute; right: 4px; bottom: 3px; font-family: var(--mono); font-size: 8px; color: var(--text); background: rgba(0,0,0,.45); padding: 0 2px; }
.slot.active .slot-key { color: var(--mint); }

/* action cluster */
.action-cluster {
  position: absolute; right: calc(24px + var(--safe-r)); bottom: calc(22px + var(--safe-b));
  display: grid; grid-template-columns: 44px 44px; gap: 8px; justify-items: end;
  align-items: end;
}
.round-btn {
  position: relative; display: grid; place-items: center; border-radius: 50%;
  background: rgba(6,15,17,.78); border: 1px solid var(--line);
  color: var(--muted); backdrop-filter: blur(10px); transition: transform .12s, border-color .2s, color .2s, background .2s;
}
.round-btn:hover { border-color: var(--line-strong); color: var(--mint); }
.round-btn.small { width: 44px; height: 44px; padding: 11px; }
.round-btn.small svg { width: 22px; height: 22px; }
.round-btn.action {
  grid-column: 1 / -1; width: 108px; height: 108px; padding: 0;
  background: radial-gradient(circle at 50% 38%, rgba(116,240,200,.2), rgba(5,17,17,.9) 68%);
  border: 1px solid var(--line-strong); color: var(--mint);
  display: flex; flex-direction: column; justify-content: center; gap: 1px;
  box-shadow: 0 0 0 5px rgba(116,240,200,.04), 0 0 34px rgba(116,240,200,.12);
}
.round-btn.action::before { content: ""; position: absolute; inset: -8px; border-radius: 50%; border: 1px dashed rgba(116,240,200,.16); animation: spin 20s linear infinite; }
.round-btn.action:hover { background: radial-gradient(circle at 50% 38%, rgba(116,240,200,.3), rgba(5,17,17,.92) 68%); }
.round-btn.action:active { transform: scale(.96); }
.round-btn.action svg { width: 25px; height: 25px; margin-bottom: 2px; }
.round-btn.action b { font-family: var(--mono); font-size: 10px; letter-spacing: .12em; }
.round-btn.action small { font-family: var(--mono); font-size: 7px; letter-spacing: .08em; color: var(--muted); }
.round-btn.action.ready { animation: actionReady 1.3s ease-in-out infinite; }
@keyframes actionReady { 50% { box-shadow: 0 0 0 9px rgba(255,200,107,.06), 0 0 40px rgba(255,200,107,.28); border-color: var(--amber); } }
.round-btn.action.hot { border-color: var(--amber); color: var(--amber); background: radial-gradient(circle at 50% 38%, rgba(255,200,107,.2), rgba(17,13,6,.9) 68%); }
.cast-readout {
  position: absolute; right: 4px; bottom: 126px; width: 136px; text-align: right;
}
.cast-readout span { font-family: var(--mono); font-size: 8px; letter-spacing: .14em; color: var(--amber); }
.cast-readout i { display: block; height: 3px; background: rgba(255,255,255,.1); margin-top: 6px; }
.cast-readout i b { display: block; height: 100%; width: 0%; background: var(--amber); box-shadow: 0 0 8px var(--amber); }

/* joystick */
.joystick { position: absolute; left: calc(22px + var(--safe-l)); bottom: calc(28px + var(--safe-b)); width: 104px; display: grid; justify-items: center; gap: 7px; }
.stick-base {
  width: 104px; height: 104px; border-radius: 50%;
  background: radial-gradient(circle, rgba(116,240,200,.05), rgba(5,13,15,.45) 70%);
  border: 1px solid rgba(116,240,200,.22); position: relative;
  box-shadow: inset 0 0 30px rgba(0,0,0,.4);
}
.stick-base::before, .stick-base::after { content: ""; position: absolute; background: rgba(116,240,200,.12); }
.stick-base::before { width: 30px; height: 1px; left: 37px; top: 51px; }
.stick-base::after { width: 1px; height: 30px; left: 51px; top: 37px; }
.stick-knob {
  position: absolute; width: 46px; height: 46px; border-radius: 50%; left: 29px; top: 29px;
  background: radial-gradient(circle at 40% 35%, rgba(166,255,226,.75), rgba(52,160,136,.45) 60%, rgba(20,70,62,.65));
  border: 1px solid rgba(166,255,226,.55); box-shadow: 0 0 20px rgba(116,240,200,.25);
}
.joystick > span { font-family: var(--mono); font-size: 7px; letter-spacing: .22em; color: var(--muted); }

/* banners / toasts */
.bite-banner {
  position: absolute; left: 50%; top: 30%; transform: translate(-50%, -50%);
  display: flex; align-items: center; gap: 10px; padding: 9px 20px;
  background: rgba(10,20,16,.86); border: 1px solid var(--amber); color: var(--amber);
  font-family: var(--mono); font-size: 13px; letter-spacing: .2em; font-weight: 700;
  box-shadow: 0 0 40px rgba(255,200,107,.22); animation: bitePulse .5s ease-in-out infinite alternate;
}
.bite-banner span { width: 22px; height: 22px; border: 1px solid var(--amber); border-radius: 50%; display: grid; place-items: center; font-size: 14px; }
@keyframes bitePulse { from { transform: translate(-50%, -50%) scale(1) } to { transform: translate(-50%, -50%) scale(1.05) } }
.banner {
  position: absolute; top: 20%; left: 50%; transform: translateX(-50%);
  display: grid; justify-items: center; gap: 4px; text-align: center; pointer-events: none;
  animation: bannerIn .5s ease both;
}
.banner small { font-family: var(--mono); font-size: 9px; letter-spacing: .3em; color: var(--mint); }
.banner strong { font-size: clamp(22px, 3vw, 38px); letter-spacing: .08em; text-transform: uppercase; font-weight: 900; text-shadow: 0 4px 30px rgba(0,0,0,.8); }
.banner span { font-size: 11px; color: var(--muted); letter-spacing: .08em; }
.banner.danger small, .banner.danger strong { color: var(--red); }
@keyframes bannerIn { from { opacity: 0; transform: translate(-50%, 12px) } to { opacity: 1; transform: translate(-50%, 0) } }
.toast-stack { position: absolute; right: calc(22px + var(--safe-r)); top: calc(76px + var(--safe-t)); display: grid; gap: 7px; justify-items: end; }
.toast {
  display: flex; align-items: center; gap: 9px; min-width: 190px; max-width: 290px;
  padding: 9px 12px; background: rgba(5,14,16,.88); border: 1px solid var(--line);
  font-size: 10px; color: var(--text); animation: toastIn .25s ease both;
  backdrop-filter: blur(10px);
}
.toast .t-icon { width: 22px; height: 22px; color: var(--mint); flex: 0 0 auto; }
.toast b { display: block; font-size: 10px; font-weight: 600; }
.toast small { display: block; font-family: var(--mono); font-size: 8px; color: var(--muted); margin-top: 1px; }
.toast.warn { border-color: rgba(255,200,107,.6); }
.toast.warn .t-icon { color: var(--amber); }
.toast.bad { border-color: rgba(255,107,125,.6); }
.toast.bad .t-icon { color: var(--red); }
.toast.out { animation: toastOut .25s ease both; }
@keyframes toastIn { from { opacity: 0; transform: translateX(18px) } to { opacity: 1; transform: none } }
@keyframes toastOut { to { opacity: 0; transform: translateX(18px) } }

.look-hint {
  position: absolute; left: 50%; top: 58%; transform: translateX(-50%);
  padding: 9px 16px; background: rgba(5,13,15,.8); border: 1px solid var(--line-strong);
  font-family: var(--mono); font-size: 9px; letter-spacing: .16em; color: var(--mint); text-transform: uppercase;
}
.lock-overlay {
  position: fixed; inset: 0; z-index: 25; display: grid; place-items: center; gap: 6px;
  background: rgba(2,6,8,.5); backdrop-filter: blur(2px); cursor: pointer;
}
.lock-overlay span { font-family: var(--mono); font-size: 12px; letter-spacing: .2em; color: var(--mint); text-transform: uppercase; }
.lock-overlay small { font-size: 9px; color: var(--muted); letter-spacing: .08em; }

/* ==========================================================================
   PANELS
   ========================================================================== */
.side-panel {
  position: fixed; z-index: 20; top: 0; right: 0; bottom: 0;
  width: min(390px, 100vw); padding: calc(20px + var(--safe-t)) 20px calc(18px + var(--safe-b));
  background: linear-gradient(160deg, rgba(7,17,19,.98), rgba(4,10,12,.98));
  border-left: 1px solid var(--line); box-shadow: -30px 0 80px rgba(0,0,0,.5);
  display: flex; flex-direction: column; animation: panelIn .28s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes panelIn { from { transform: translateX(30px); opacity: 0 } to { transform: none; opacity: 1 } }
.panel-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding-bottom: 16px; border-bottom: 1px solid var(--line); }
.panel-head h2 { font-size: 26px; letter-spacing: -.02em; margin-top: 4px; }
.eyebrow { font-family: var(--mono); font-size: 8px; letter-spacing: .26em; color: var(--mint); text-transform: uppercase; }
.inv-meta { display: flex; justify-content: space-between; padding: 12px 0 10px; font-family: var(--mono); font-size: 9px; letter-spacing: .08em; color: var(--muted); }
.inv-meta span:last-child { color: var(--mint); }
.inv-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; }
.inv-slot {
  position: relative; aspect-ratio: 1; display: grid; place-items: center;
  background: rgba(255,255,255,.032); border: 1px solid rgba(255,255,255,.07);
  color: var(--muted); transition: .15s;
}
.inv-slot:hover { border-color: var(--line-strong); background: rgba(116,240,200,.06); }
.inv-slot.selected { border-color: var(--mint); background: rgba(116,240,200,.12); color: var(--mint); }
.inv-slot.locked { opacity: .22; border-style: dashed; }
.inv-slot .slot-icon { width: 24px; height: 24px; }
.inv-slot .slot-count { position: absolute; right: 4px; bottom: 3px; font-family: var(--mono); font-size: 8px; color: var(--text); }
.inv-slot .rar { position: absolute; left: 4px; top: 3px; width: 4px; height: 4px; border-radius: 50%; }
.inv-detail {
  margin-top: 14px; padding: 13px; min-height: 110px;
  background: rgba(255,255,255,.028); border: 1px solid rgba(255,255,255,.055);
  display: flex; flex-direction: column; gap: 6px;
}
.inv-detail .empty-hint { margin: auto; font-family: var(--mono); font-size: 9px; color: var(--dim); letter-spacing: .06em; }
.detail-head { display: flex; align-items: center; gap: 10px; }
.detail-icon { width: 34px; height: 34px; color: var(--mint); flex: 0 0 auto; }
.detail-head h3 { font-size: 13px; }
.detail-head span { display: block; font-family: var(--mono); font-size: 8px; letter-spacing: .14em; text-transform: uppercase; margin-top: 2px; }
.detail-desc { font-size: 10px; line-height: 1.5; color: var(--muted); }
.detail-actions { display: flex; gap: 6px; margin-top: auto; padding-top: 8px; }
.detail-actions button {
  flex: 1; min-height: 30px; border: 1px solid var(--line); background: rgba(116,240,200,.06);
  font-family: var(--mono); font-size: 8px; letter-spacing: .14em; text-transform: uppercase; color: var(--mint);
}
.detail-actions button:hover { background: rgba(116,240,200,.16); }
.detail-actions button.danger { color: var(--red); border-color: rgba(255,107,125,.25); background: rgba(255,107,125,.04); }
.panel-foot { margin-top: auto; padding-top: 12px; border-top: 1px solid var(--line); display: flex; justify-content: space-between; gap: 10px; font-family: var(--mono); font-size: 8px; color: var(--dim); letter-spacing: .04em; }
.panel-intro { font-size: 10px; line-height: 1.55; color: var(--muted); padding: 12px 0; }
.recipe-list { display: grid; gap: 8px; overflow-y: auto; padding-right: 4px; }
.recipe {
  display: grid; grid-template-columns: 42px 1fr auto; gap: 10px; align-items: center;
  padding: 11px; background: rgba(255,255,255,.028); border: 1px solid rgba(255,255,255,.06);
}
.recipe-icon { width: 34px; height: 34px; color: var(--mint); }
.recipe h3 { font-size: 12px; display: flex; align-items: center; gap: 8px; }
.recipe h3 span { font-family: var(--mono); font-size: 7px; color: var(--dim); letter-spacing: .12em; text-transform: uppercase; border: 1px solid var(--line); padding: 1px 4px; }
.recipe p { font-size: 9px; line-height: 1.45; color: var(--muted); margin-top: 3px; }
.recipe-cost { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 6px; }
.cost { display: inline-flex; align-items: center; gap: 3px; font-family: var(--mono); font-size: 8px; color: var(--muted); padding: 2px 5px; background: rgba(0,0,0,.25); }
.cost.missing { color: var(--red); }
.cost .mini { width: 12px; height: 12px; }
.craft-btn { min-width: 62px; padding: 8px 6px; border: 1px solid var(--line-strong); background: rgba(116,240,200,.1); color: var(--mint); font-family: var(--mono); font-size: 8px; letter-spacing: .1em; }
.craft-btn:disabled { opacity: .3; color: var(--muted); border-color: rgba(255,255,255,.1); background: none; cursor: not-allowed; }
.craft-btn:not(:disabled):hover { background: rgba(116,240,200,.22); }

/* settings modal */
.modal-card {
  position: fixed; z-index: 24; left: 50%; top: 50%; transform: translate(-50%, -50%);
  width: min(420px, calc(100vw - 32px)); padding: 20px;
  background: linear-gradient(160deg, rgba(8,19,21,.98), rgba(4,10,12,.98));
  border: 1px solid var(--line); box-shadow: var(--shadow);
  animation: cardIn .24s ease both;
}
@keyframes cardIn { from { opacity: 0; transform: translate(-50%, -47%) } to { opacity: 1; transform: translate(-50%, -50%) } }
.setting-row { display: grid; grid-template-columns: 1fr 150px 42px; align-items: center; gap: 10px; padding: 14px 0; border-bottom: 1px solid rgba(255,255,255,.06); font-size: 11px; color: var(--muted); }
.setting-row b { font-family: var(--mono); font-size: 9px; color: var(--text); text-align: right; }
.setting-row input[type=range] { -webkit-appearance: none; width: 100%; height: 3px; background: rgba(255,255,255,.14); outline: none; }
.setting-row input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 13px; height: 13px; border-radius: 50%; background: var(--mint); box-shadow: 0 0 10px rgba(116,240,200,.6); }
.setting-row input[type=range]::-moz-range-thumb { width: 13px; height: 13px; border: 0; border-radius: 50%; background: var(--mint); }
.toggle { width: 38px; height: 20px; justify-self: end; border-radius: 12px; background: rgba(255,255,255,.14); position: relative; }
.toggle i { position: absolute; width: 14px; height: 14px; border-radius: 50%; background: var(--muted); left: 3px; top: 3px; transition: .2s; }
.toggle.on { background: rgba(116,240,200,.26); }
.toggle.on i { left: 21px; background: var(--mint); box-shadow: 0 0 8px var(--mint); }
.setting-actions { display: flex; gap: 8px; padding-top: 16px; }
.small-btn { min-height: 38px; padding: 0 14px; font-family: var(--mono); font-size: 9px; letter-spacing: .1em; }
.danger-btn { border: 1px solid rgba(255,107,125,.3); color: var(--red); background: rgba(255,107,125,.05); }
.danger-btn:hover { background: rgba(255,107,125,.12); }
.credit { font-size: 8px; color: var(--dim); line-height: 1.5; padding-top: 14px; }

/* ==========================================================================
   OVERLAYS
   ========================================================================== */
.overlay {
  position: fixed; inset: 0; z-index: 26; display: grid; place-items: center;
  background: rgba(2,6,8,.66); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
  padding: 18px;
}
.loot-card, .end-card {
  position: relative; width: min(430px, 100%); padding: 22px;
  background: linear-gradient(155deg, rgba(9,22,23,.98), rgba(4,10,12,.99));
  border: 1px solid var(--line-strong); box-shadow: 0 30px 90px rgba(0,0,0,.6);
  animation: cardIn .3s ease both;
}
.loot-card::before, .end-card::before { content: ""; position: absolute; inset: 6px; border: 1px solid rgba(116,240,200,.06); pointer-events: none; }
.loot-head { display: flex; align-items: flex-start; gap: 10px; padding-bottom: 14px; border-bottom: 1px solid var(--line); }
.loot-head h2 { font-size: 22px; letter-spacing: -.01em; }
.rarity-chip { margin-left: auto; font-family: var(--mono); font-size: 8px; letter-spacing: .14em; padding: 4px 7px; border: 1px solid currentColor; color: var(--muted); }
.loot-items { display: grid; gap: 6px; padding: 14px 0 0; }
.loot-item { display: grid; grid-template-columns: 32px 1fr auto; align-items: center; gap: 10px; padding: 8px 10px; background: rgba(255,255,255,.03); border-left: 2px solid var(--rarity, var(--line)); animation: lootIn .3s ease both; }
@keyframes lootIn { from { opacity: 0; transform: translateY(6px) } to { opacity: 1; transform: none } }
.loot-item .l-icon { width: 26px; height: 26px; color: var(--rarity, var(--mint)); }
.loot-item b { font-size: 11px; display: block; }
.loot-item small { display: block; font-family: var(--mono); font-size: 7px; letter-spacing: .1em; color: var(--muted); margin-top: 2px; text-transform: uppercase; }
.loot-item em { font-family: var(--mono); font-size: 11px; color: var(--text); font-style: normal; }
.loot-note { font-size: 9px; color: var(--dim); margin-top: 12px; text-align: center; }
.end-card { text-align: center; width: min(480px, 100%); padding: 34px 28px 26px; overflow: hidden; }
.end-glow { position: absolute; width: 280px; height: 280px; left: 50%; top: -140px; transform: translateX(-50%); background: radial-gradient(circle, rgba(255,107,125,.3), transparent 65%); pointer-events: none; }
.end-glow.gold { background: radial-gradient(circle, rgba(255,200,107,.34), transparent 65%); }
.end-card h2 { font-size: clamp(28px, 5vw, 44px); line-height: .95; letter-spacing: -.03em; margin: 10px 0 12px; font-weight: 900; }
.death .end-card h2 { color: #ffd9de; }
.victory .end-card h2 span { color: var(--amber); }
.end-card > p:not(.eyebrow) { font-size: 11px; line-height: 1.6; color: var(--muted); max-width: 340px; margin: 0 auto; }
.end-stats { display: flex; justify-content: center; gap: 22px; margin: 20px 0; padding: 14px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.end-stat { text-align: center; }
.end-stat b { display: block; font-family: var(--mono); font-size: 17px; color: var(--mint); }
.end-stat span { display: block; font-family: var(--mono); font-size: 7px; letter-spacing: .14em; color: var(--dim); text-transform: uppercase; margin-top: 3px; }
.text-btn { display: block; margin: 12px auto 0; font-family: var(--mono); font-size: 8px; letter-spacing: .14em; color: var(--dim); text-decoration: underline; text-underline-offset: 3px; }
.text-btn:hover { color: var(--muted); }
.rotate-note {
  position: fixed; z-index: 22; left: 50%; bottom: calc(16px + var(--safe-b)); transform: translateX(-50%);
  display: flex; align-items: center; gap: 6px; background: rgba(5,13,15,.8); border: 1px solid var(--line);
  padding: 7px 12px; font-family: var(--mono); font-size: 8px; letter-spacing: .12em; color: var(--muted);
}

