page.on('console', (m) => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE', m.text()) } })

await page.goto('http://localhost:3002/?debug=1', { waitUntil: 'networkidle' })
await page.evaluate(() => localStorage.clear())
await page.reload({ waitUntil: 'networkidle' })
await page.waitForTimeout(900)
await page.click('#start-btn')
await page.waitForTimeout(5200)
const shot = async (name) => { await page.waitForTimeout(400); await page.screenshot({ path: `screenshots/${name}.jpg`, type: 'jpeg', quality: 82 }) }
const api = (fn, ...args) => page.evaluate(fn, ...args)

console.log('debug api', await api(() => !!window.__VOIDLINE__))
await api(() => {
  const g = window.__VOIDLINE__
  g.addItem('axe', 1)
  g.addItem('spear', 1)
  g.addItem('blade', 1)
  g.equipItem('axe')
  g.player.pitch = -0.12
})
await shot('14-axe')

await api(() => {
  const g = window.__VOIDLINE__
  g.equipItem('rod')
  g.world.placeCampfire(0, -1)
  g.state.flags.campfire = true
  g.refreshAll()
})
await shot('15-fire')

await api(() => {
  const g = window.__VOIDLINE__
  g.addItem('deed', 3)
  g.startBuildMode()
})
await shot('16-build')

const buildInfo = await api(() => {
  const g = window.__VOIDLINE__
  return { ghosts: g.world.ghosts.length, actions: document.querySelector('#action-label').textContent, toast: [...document.querySelectorAll('.toast b')].map(n => n.textContent) }
})
console.log('build', buildInfo)

await api(() => { window.__VOIDLINE__.cancelBuild() })
await page.waitForTimeout(500)

// Trial + boss
await api(() => {
  const g = window.__VOIDLINE__
  g.startTrial()
  g.state.day = 8
  g.state.dayProgress = 0.1
  g.world.clearMonsters()
  g.state.bossSpawned = true
  g.state.nextSpawn = 999
  const m = g.world.spawnMonster('herald', 0.4, -3.6)
  m.speed = 0
  g.equipItem('blade')
  g.player.yaw = 0
  g.player.pitch = -0.05
})
await page.waitForTimeout(5600)
await shot('17-boss')
console.log('boss state', await api(() => {
  const g = window.__VOIDLINE__
  const b = g.world.monsters.find(m => m.boss)
  return { boss: !!b, hp: b?.hp, bar: !document.querySelector('#boss-bar').classList.contains('hidden'), actions: document.querySelector('#action-label').textContent }
}))

// Kill the boss and check victory
await api(() => {
  const g = window.__VOIDLINE__
  const b = g.world.monsters.find(m => m.boss)
  b.hp = 1
  g.player.pitch = 0
  document.querySelector('#action-btn').dispatchEvent(new Event('pointerdown', { bubbles: true }))
})
await page.waitForTimeout(2200)
const win = await page.evaluate(() => ({
  victory: !document.querySelector('#victory-overlay').classList.contains('hidden'),
  stats: document.querySelector('#victory-stats')?.textContent,
  postGame: window.__VOIDLINE__.state().postGame,
  core: window.__VOIDLINE__.state().inventory.some(i => i.id === 'core'),
}))
console.log('win', win)
await shot('18-victory')

// Death flow
await page.click('#victory-btn')
await page.waitForTimeout(500)
await api(() => { const g = window.__VOIDLINE__; g.state.health = 20; g.damagePlayer(200) })
await page.waitForTimeout(700)
console.log('death', await page.evaluate(() => ({
  open: !document.querySelector('#death-overlay').classList.contains('hidden'),
  text: document.querySelector('#death-stats')?.textContent,
  dead: window.__VOIDLINE__.state().dead,
})))
await shot('19-death')

console.log('errors', errors.slice(0, 20))
await browser.close()

