    this.bobber.rotation.y = now * 0.7
    const ring = this.bobber.userData.ring
    if (ring) ring.rotation.z = now
  }
  if (this.castRing.visible) {
    this.castInner.rotation.y = -now
    this.castOuter.rotation.y = now * 0.6
  }
